def main():
 for i,n in {51:'Mighty Fighter',55:'Bold Explorer',61:'Oni Sword Maiden',85:'Budding Mage',98:'Black Oak Knight',171:'Divine Smith',196:'Atoning Mage',247:'Thrower',284:'Demonbug Queen',353:'Great Lamp Imp'}.items():NAMES[i]=n
